import accounts.AccountType;
import accounts.BankUser;
import accounts.CheckingAccount;
import accounts.SavingsAccount;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertThrows;

/**
 * This class was ai generated by chatGPT. It mirors the checking account tests and is also verified.
 */
public class SavingsAccountTest {
    private CheckingAccount checking;
    private SavingsAccount saving;

    @Before
    public void setUp() {
        BankUser user = new BankUser("test-user", "test-password");
        checking = new CheckingAccount(user, AccountType.CHECKING);
        saving = new SavingsAccount(user, AccountType.SAVINGS);

        user.getAccounts().add(checking);
        user.getAccounts().add(saving);
    }

    @Test
    public void acceptsDepositsAtDailyLimit() {
        saving.deposit(4999);
        saving.deposit(1);

        assertEquals(5000, saving.getBalance());
    }

    @Test
    public void rejectsSingleDepositAboveDailyLimit() {
        assertThrows(IllegalArgumentException.class, () -> saving.deposit(5001));

        assertEquals(0, saving.getBalance());
    }

    @Test
    public void rejectsDepositsAboveCumulativeDailyLimit() {
        saving.deposit(1000);

        assertThrows(IllegalArgumentException.class, () -> saving.deposit(4001));

        assertEquals(1000, saving.getBalance());
    }

    @Test
    public void rejectsZeroAndNegativeDeposits() {
        assertThrows(IllegalArgumentException.class, () -> saving.deposit(0));
        assertThrows(IllegalArgumentException.class, () -> saving.deposit(-1));

        assertEquals(0, saving.getBalance());
    }

    @Test
    public void transfersToCheckingUpToDailyLimit() {
        saving.deposit(200);

        saving.transfer(99, AccountType.CHECKING);
        saving.transfer(1, AccountType.CHECKING);

        assertEquals(100, saving.getBalance());
        assertEquals(100, checking.getBalance());
    }

    @Test
    public void rejectsTransferAboveCumulativeDailyLimit() {
        saving.deposit(200);
        saving.transfer(100, AccountType.CHECKING);

        assertThrows(IllegalArgumentException.class,
                () -> saving.transfer(1, AccountType.CHECKING));

        assertEquals(100, saving.getBalance());
        assertEquals(100, checking.getBalance());
    }

    @Test
    public void rejectsTransferAboveAvailableBalance() {
        saving.deposit(50);

        assertThrows(IllegalArgumentException.class,
                () -> saving.transfer(51, AccountType.CHECKING));

        assertEquals(50, saving.getBalance());
        assertEquals(0, checking.getBalance());
    }
}